function printTriangle(int $n): void
{
    if ($n < 1) {
        throw new InvalidArgumentException("Size must be at least 1");
    }

    for ($i = 1; $i <= $n; $i++) {
        echo str_repeat("*", $i) . PHP_EOL;
    }
}

printTriangle(5);

